import type { Circuit, Constructor, Driver } from "@pitwall/shared";
import { circuitFor, circuitIdAt } from "./circuits";
import registry from "./openf1-map.json";

// Generated by scripts/gen-openf1-map.mjs from Jolpica and OpenF1. OpenF1 identifies drivers by number and
// teams by name; the app links everything by Jolpica id, so OpenF1 seasons are mapped through this file.
type Info<T> = Omit<T, "id"> & { seasons: number[] };
const drivers = registry.drivers as Record<string, Info<Driver>>;
const constructors = registry.constructors as Record<string, Info<Constructor>>;
const circuits = registry.circuits as Record<string, { name: string; locality: string; country: string; lat: number; lon: number }>;
const seasons = registry.seasons as Record<string, { numbers: Record<string, string>; teams: Record<string, string> }>;

const withoutSeasons = <T extends { seasons: number[] }>({ seasons: _, ...rest }: T) => rest;

/** Name fields as OpenF1 publishes them on a driver row. */
export interface OpenF1Name {
  name_acronym?: string | null;
  first_name?: string | null;
  last_name?: string | null;
  full_name?: string | null;
}

export const driverIdFor = (season: number, number: number): string | null => seasons[season]?.numbers[number] ?? null;

/** Jolpica driver for an OpenF1 car; unmapped cars keep id "" and OpenF1's own names. */
export function driverFor(season: number, number: number, name: OpenF1Name | undefined): Driver {
  const id = driverIdFor(season, number);
  const known = id ? drivers[id] : undefined;
  if (id && known) return { id, ...withoutSeasons(known) };
  return {
    id: "",
    code: name?.name_acronym ?? null,
    number,
    givenName: name?.first_name ?? "",
    familyName: name?.last_name ?? name?.full_name ?? name?.name_acronym ?? `Car ${number}`,
    nationality: null,
    dateOfBirth: null,
    url: null,
  };
}

/** Jolpica constructor for an OpenF1 team name; unmapped teams keep id "". */
export function constructorFor(season: number, teamName: string | null | undefined): Constructor {
  const id = teamName ? seasons[season]?.teams[teamName] : undefined;
  const known = id ? constructors[id] : undefined;
  if (id && known) return { id, ...withoutSeasons(known) };
  return { id: "", name: teamName ?? "Unknown team", nationality: null, url: null };
}

/** Identity and every season entered, for drivers and constructors seen in OpenF1 seasons. */
export function mappedSubject(kind: "drivers" | "constructors", id: string) {
  if (kind === "drivers") {
    const d = drivers[id];
    return d ? { driver: { id, ...withoutSeasons(d) }, seasons: d.seasons } : null;
  }
  const c = constructors[id];
  return c ? { constructor: { id, ...withoutSeasons(c) }, seasons: c.seasons } : null;
}

const toCircuit = (id: string, season: number, round: number): Circuit | null => {
  const c = circuits[id];
  return c
    ? circuitFor({ circuitId: id, circuitName: c.name, Location: { lat: String(c.lat), long: String(c.lon), locality: c.locality, country: c.country } }, season, round)
    : null;
};

/** Circuit of an OpenF1 round (OpenF1's own circuit keys aren't reliable). */
export function circuitAt(season: number, round: number): Circuit | null {
  const id = circuitIdAt(season, round);
  return id ? toCircuit(id, season, round) : null;
}

export const circuitById = (id: string): Circuit | null => toCircuit(id, 0, 0);
